create table if not exists public.network_founder_identity_registry (id uuid primary key default gen_random_uuid(), founder_user_id uuid not null references public.users(id) on delete restrict, legal_name text not null check (length(btrim(legal_name)) >= 2), jurisdiction text not null check (length(btrim(jurisdiction)) >= 2), identity_document_fingerprint text not null check (identity_document_fingerprint ~ '^[0-9a-fA-F]{64}$'), status text not null default 'active' check (status in ('active','suspended','revoked')), effective_from timestamptz not null default now(), effective_to timestamptz, created_at timestamptz not null default now(), created_by uuid not null references public.users(id) on delete restrict, check (effective_to is null or effective_to > effective_from));
create unique index if not exists network_founder_identity_active_uidx on public.network_founder_identity_registry(status) where status='active';
create unique index if not exists network_founder_identity_user_uidx on public.network_founder_identity_registry(founder_user_id) where status='active';
create table if not exists public.network_platform_ip_assets (id uuid primary key default gen_random_uuid(), asset_key text not null check (asset_key ~ '^[a-z0-9][a-z0-9_.-]{1,127}$'), asset_type text not null check (asset_type in ('software','database_schema','algorithm','brand','documentation','design','process','other')), title text not null check (length(btrim(title)) >= 2), description text, owner_founder_identity_id uuid not null references public.network_founder_identity_registry(id) on delete restrict, current_version integer not null default 1 check (current_version >= 1), status text not null default 'active' check (status in ('draft','active','retired','disputed')), created_at timestamptz not null default now(), created_by uuid not null references public.users(id) on delete restrict, unique(asset_key));
create table if not exists public.network_platform_ip_asset_versions (id uuid primary key default gen_random_uuid(), asset_id uuid not null references public.network_platform_ip_assets(id) on delete restrict, version_no integer not null check (version_no >= 1), content_digest text not null check (content_digest ~ '^[0-9a-fA-F]{64}$'), source_commit_digest text check (source_commit_digest is null or source_commit_digest ~ '^[0-9a-fA-F]{40,64}$'), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), created_by uuid not null references public.users(id) on delete restrict, unique(asset_id,version_no), unique(asset_id,content_digest));
create table if not exists public.network_ip_provenance_events (id bigint generated always as identity primary key, asset_id uuid not null references public.network_platform_ip_assets(id) on delete restrict, asset_version_id uuid references public.network_platform_ip_asset_versions(id) on delete restrict, event_type text not null check (event_type in ('registered','versioned','transferred','licensed','retired','disputed','restored')), actor_user_id uuid not null references public.users(id) on delete restrict, payload jsonb not null default '{}'::jsonb, previous_hash text, event_hash text not null check (event_hash ~ '^[0-9a-fA-F]{64}$'), created_at timestamptz not null default now(), unique(event_hash));
create index if not exists network_ip_provenance_asset_idx on public.network_ip_provenance_events(asset_id,id);
create table if not exists public.network_root_key_registry (id uuid primary key default gen_random_uuid(), key_purpose text not null check (key_purpose in ('platform_root','provenance_signing','financial_authorization','break_glass')), kms_provider text not null check (length(btrim(kms_provider)) >= 2), kms_key_reference text not null check (length(btrim(kms_key_reference)) >= 2), public_key_fingerprint text not null check (public_key_fingerprint ~ '^[0-9a-fA-F]{64}$'), algorithm text not null check (length(btrim(algorithm)) >= 2), status text not null default 'active' check (status in ('active','rotating','retired','revoked')), activated_at timestamptz not null default now(), retired_at timestamptz, created_at timestamptz not null default now(), created_by uuid not null references public.users(id) on delete restrict, check (retired_at is null or retired_at >= activated_at));
create unique index if not exists network_root_key_active_purpose_uidx on public.network_root_key_registry(key_purpose) where status='active';
create table if not exists public.network_signing_workflows (id uuid primary key default gen_random_uuid(), workflow_type text not null check (workflow_type in ('ip_registration','ip_transfer','key_rotation','break_glass','platform_change')), subject_type text not null, subject_id uuid not null, required_signatures integer not null check (required_signatures >= 1), collected_signatures integer not null default 0 check (collected_signatures >= 0 and collected_signatures <= required_signatures), status text not null default 'pending' check (status in ('pending','approved','executed','rejected','expired','cancelled')), expires_at timestamptz, created_at timestamptz not null default now(), created_by uuid not null references public.users(id) on delete restrict, executed_at timestamptz);
create table if not exists public.network_signing_workflow_signatures (id bigint generated always as identity primary key, workflow_id uuid not null references public.network_signing_workflows(id) on delete restrict, signer_user_id uuid not null references public.users(id) on delete restrict, key_registry_id uuid not null references public.network_root_key_registry(id) on delete restrict, signature_digest text not null check (signature_digest ~ '^[0-9a-fA-F]{64}$'), signed_payload_digest text not null check (signed_payload_digest ~ '^[0-9a-fA-F]{64}$'), created_at timestamptz not null default now(), unique(workflow_id,signer_user_id), unique(workflow_id,signature_digest));
create table if not exists public.network_break_glass_events (id bigint generated always as identity primary key, workflow_id uuid not null references public.network_signing_workflows(id) on delete restrict, actor_user_id uuid not null references public.users(id) on delete restrict, reason text not null check (length(btrim(reason)) >= 20), scope jsonb not null, authorization_digest text not null check (authorization_digest ~ '^[0-9a-fA-F]{64}$'), executed_at timestamptz not null default now(), revoked_at timestamptz, check (revoked_at is null or revoked_at >= executed_at), unique(authorization_digest));
create or replace function public.v33_hash_provenance_payload(p_asset_id uuid,p_asset_version_id uuid,p_event_type text,p_actor uuid,p_payload jsonb,p_previous text,p_created_at timestamptz) returns text language sql immutable strict security invoker set search_path=pg_catalog,public,extensions,pg_temp as $$ select encode(digest(coalesce(p_asset_id::text,'')||'|'||coalesce(p_asset_version_id::text,'')||'|'||p_event_type||'|'||p_actor::text||'|'||p_payload::text||'|'||coalesce(p_previous,'')||'|'||p_created_at::text,'sha256'),'hex') $$;
create or replace function public.v33_append_provenance_event(p_asset_id uuid,p_asset_version_id uuid,p_event_type text,p_actor_user_id uuid,p_payload jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=pg_catalog,public,extensions,pg_temp as $$ declare v_prev text; v_hash text; v_id bigint; v_now timestamptz:=clock_timestamp(); begin perform pg_advisory_xact_lock(hashtextextended('nabuuma:v33:ip:'||p_asset_id::text,0)); select event_hash into v_prev from public.network_ip_provenance_events where asset_id=p_asset_id order by id desc limit 1; v_hash:=public.v33_hash_provenance_payload(p_asset_id,p_asset_version_id,p_event_type,p_actor_user_id,p_payload,v_prev,v_now); insert into public.network_ip_provenance_events(asset_id,asset_version_id,event_type,actor_user_id,payload,previous_hash,event_hash,created_at) values(p_asset_id,p_asset_version_id,p_event_type,p_actor_user_id,p_payload,v_prev,v_hash,v_now) returning id into v_id; return v_id; end $$;
revoke all on function public.v33_append_provenance_event(uuid,uuid,text,uuid,jsonb) from public,anon,authenticated; grant execute on function public.v33_append_provenance_event(uuid,uuid,text,uuid,jsonb) to service_role;
create or replace function public.v33_protect_immutable_ip_provenance() returns trigger language plpgsql security invoker set search_path=pg_catalog,public,extensions,pg_temp as $$ begin raise exception 'v3.3 provenance records are append-only'; end $$;
drop trigger if exists network_ip_provenance_immutable_trg on public.network_ip_provenance_events; create trigger network_ip_provenance_immutable_trg before update or delete on public.network_ip_provenance_events for each row execute function public.v33_protect_immutable_ip_provenance();
create or replace function public.v33_validate_provenance_hash() returns trigger language plpgsql security invoker set search_path=pg_catalog,public,extensions,pg_temp as $$ begin if new.event_hash <> public.v33_hash_provenance_payload(new.asset_id,new.asset_version_id,new.event_type,new.actor_user_id,new.payload,new.previous_hash,new.created_at) then raise exception 'invalid v3.3 provenance event hash'; end if; return new; end $$;
drop trigger if exists network_ip_provenance_hash_trg on public.network_ip_provenance_events; create trigger network_ip_provenance_hash_trg before insert on public.network_ip_provenance_events for each row execute function public.v33_validate_provenance_hash();
alter table public.network_founder_identity_registry enable row level security; alter table public.network_platform_ip_assets enable row level security; alter table public.network_platform_ip_asset_versions enable row level security; alter table public.network_ip_provenance_events enable row level security; alter table public.network_root_key_registry enable row level security; alter table public.network_signing_workflows enable row level security; alter table public.network_signing_workflow_signatures enable row level security; alter table public.network_break_glass_events enable row level security;
revoke all on public.network_founder_identity_registry,public.network_platform_ip_assets,public.network_platform_ip_asset_versions,public.network_ip_provenance_events,public.network_root_key_registry,public.network_signing_workflows,public.network_signing_workflow_signatures,public.network_break_glass_events from public,anon,authenticated;
grant select,insert,update,delete on public.network_founder_identity_registry,public.network_platform_ip_assets,public.network_platform_ip_asset_versions,public.network_signing_workflows,public.network_signing_workflow_signatures,public.network_break_glass_events to service_role; grant select,insert on public.network_ip_provenance_events to service_role; grant select,insert,update on public.network_root_key_registry to service_role;
create index if not exists network_ip_asset_versions_asset_idx on public.network_platform_ip_asset_versions(asset_id,version_no); create index if not exists network_signing_workflows_subject_idx on public.network_signing_workflows(subject_type,subject_id); create index if not exists network_signatures_workflow_idx on public.network_signing_workflow_signatures(workflow_id); create index if not exists network_break_glass_workflow_idx on public.network_break_glass_events(workflow_id);